1	import { useState, useMemo } from "react";
2	import { Link } from "wouter";
3	import { differenceInDays, startOfDay } from "date-fns";
4	import { 
5	  useListShows, 
6	  useGetDashboardSummary 
7	} from "@workspace/api-client-react";
8	import { ShowCard } from "@/components/show-card";
9	import { Layout } from "@/components/layout";
10	import { AddShowDialog } from "@/components/add-show-dialog";
11	import { Skeleton } from "@/components/ui/skeleton";
12	import { Button } from "@/components/ui/button";
13	import { 
14	  Select, 
15	  SelectContent, 
16	  SelectItem, 
17	  SelectTrigger, 
18	  SelectValue 
19	} from "@/components/ui/select";
20	import { AlertCircle, ChevronDown, ChevronUp } from "lucide-react";
21	import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
22	import { Card, CardContent } from "@/components/ui/card";
23	import { formatDate, parseDateStr } from "@/lib/date-utils";
24	import { DashboardWeeklyCalendar } from "@/components/dashboard-weekly-calendar";
25	import { OverduePanel } from "@/components/overdue-panel";
26	
27	type SortOption = "date-asc" | "date-desc" | "name" | "overdue";
28	
29	export default function Dashboard() {
30	  const { data: shows, isLoading: showsLoading } = useListShows();
31	  const { data: summary, isLoading: summaryLoading } = useGetDashboardSummary();
32	  const [sortBy, setSortBy] = useState<SortOption>("date-asc");
33	  const [archivedOpen, setArchivedOpen] = useState(false);
34	
35	  const today = startOfDay(new Date());
36	
37	  const activeShows = useMemo(() => {
38	    if (!shows) return [];
39	    return shows.filter(s => {
40	      const cutoff = startOfDay(parseDateStr(s.dismantleDate ?? s.moveInDate));
41	      return differenceInDays(cutoff, today) >= 0;
42	    }).sort((a, b) => {
43	      if (sortBy === "date-asc") {
44	        return parseDateStr(a.moveInDate).getTime() - parseDateStr(b.moveInDate).getTime();
45	      }
46	      if (sortBy === "date-desc") {
47	        return parseDateStr(b.moveInDate).getTime() - parseDateStr(a.moveInDate).getTime();
48	      }
49	      if (sortBy === "name") {
50	        return a.name.localeCompare(b.name);
51	      }
52	      if (sortBy === "overdue") {
53	        return (b.overdueCount || 0) - (a.overdueCount || 0);
54	      }
55	      return 0;
56	    });
57	  }, [shows, sortBy, today]);
58	
59	  const archivedShows = useMemo(() => {
60	    if (!shows) return [];
61	    return shows.filter(s => {
62	      const cutoff = startOfDay(parseDateStr(s.dismantleDate ?? s.moveInDate));
63	      return differenceInDays(cutoff, today) < 0;
64	    }).sort((a, b) => parseDateStr(b.moveInDate).getTime() - parseDateStr(a.moveInDate).getTime());
65	  }, [shows, today]);
66	
67	  return (
68	    <Layout>
69	      <div className="container mx-auto p-4 md:p-6 space-y-8">
70	        
71	        {/* Next Up Banner */}
72	        {!summaryLoading && summary?.nextUpShow && (
73	          <div className="bg-primary/10 border border-primary/20 rounded-lg p-6 flex flex-col md:flex-row items-center justify-between gap-6">
74	            <div className="flex items-center gap-4">
75	              <div className="bg-primary/20 p-4 rounded-full">
76	                <AlertCircle className="h-8 w-8 text-primary" />
77	              </div>
78	              <div>
79	                <h2 className="text-sm font-semibold text-primary uppercase tracking-wider">Next Up</h2>
80	                <Link href={`/shows/${summary.nextUpShow.id}`} className="text-2xl font-bold hover:underline">
81	                  {summary.nextUpShow.name}
82	                </Link>
83	                <div className="text-muted-foreground mt-1">
84	                  Move-in: {formatDate(summary.nextUpShow.moveInDate)}
85	                  {summary.nextUpShow.venue && ` • ${summary.nextUpShow.venue}`}
86	                </div>
87	              </div>
88	            </div>
89	            
90	            <div className="text-center bg-background rounded-lg p-4 shadow-sm border min-w-[200px]">
91	              <div className="text-5xl font-black text-primary">
92	                {Math.abs(differenceInDays(startOfDay(parseDateStr(summary.nextUpShow.moveInDate)), today))}
93	              </div>
94	              <div className="text-sm font-medium text-muted-foreground uppercase tracking-wider mt-1">
95	                Days Until Move-in
96	              </div>
97	            </div>
98	          </div>
99	        )}
100	        
101	        {summaryLoading && (
102	          <Skeleton className="w-full h-32 rounded-lg" />
103	        )}
104	
105	        {/* Weekly Calendar */}
106	        <DashboardWeeklyCalendar />
107	
108	        {/* Overdue Panel */}
109	        <OverduePanel />
110	
111	        {/* Dashboard Header */}
112	        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
113	          <div>
114	            <h1 className="text-3xl font-bold tracking-tight">Active Shows</h1>
115	            <span className="text-muted-foreground mt-1 block">
116	              {summaryLoading ? <Skeleton className="w-32 h-5 inline-block" /> : `${summary?.activeShows || 0} active, ${summary?.totalOverdue || 0} items overdue`}
117	            </span>
118	          </div>
119	          
120	          <div className="flex items-center gap-3">
121	            <Select value={sortBy} onValueChange={(val) => setSortBy(val as SortOption)}>
122	              <SelectTrigger className="w-[180px]">
123	                <SelectValue placeholder="Sort by..." />
124	              </SelectTrigger>
125	              <SelectContent>
126	                <SelectItem value="date-asc">Date (Earliest First)</SelectItem>
127	                <SelectItem value="date-desc">Date (Latest First)</SelectItem>
128	                <SelectItem value="name">Name (A-Z)</SelectItem>
129	                <SelectItem value="overdue">Most Overdue</SelectItem>
130	              </SelectContent>
131	            </Select>
132	            
133	            <AddShowDialog />
134	          </div>
135	        </div>
136	
137	        {/* Active Shows Grid */}
138	        {showsLoading ? (
139	          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
140	            {[1, 2, 3].map(i => (
141	              <Skeleton key={i} className="h-[250px] rounded-xl" />
142	            ))}
143	          </div>
144	        ) : (
145	          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
146	            {activeShows.map(show => (
147	              <ShowCard key={show.id} show={show} />
148	            ))}
149	            {activeShows.length === 0 && (
150	              <div className="col-span-full py-12 text-center border-2 border-dashed rounded-xl text-muted-foreground">
151	                No active shows found. Add one to get started.
152	              </div>
153	            )}
154	          </div>
155	        )}
156	
157	        {/* Archived Shows */}
158	        {archivedShows.length > 0 && (
159	          <Collapsible
160	            open={archivedOpen}
161	            onOpenChange={setArchivedOpen}
162	            className="mt-12 space-y-4"
163	          >
164	            <div className="flex items-center justify-between">
165	              <h2 className="text-2xl font-bold tracking-tight text-muted-foreground">Archived Shows</h2>
166	              <CollapsibleTrigger asChild>
167	                <Button variant="ghost" size="sm">
168	                  {archivedOpen ? "Hide" : "Show"} ({archivedShows.length})
169	                  {archivedOpen ? <ChevronUp className="ml-2 h-4 w-4" /> : <ChevronDown className="ml-2 h-4 w-4" />}
170	                </Button>
171	              </CollapsibleTrigger>
172	            </div>
173	            
174	            <CollapsibleContent className="space-y-4">
175	              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 opacity-75 hover:opacity-100 transition-opacity">
176	                {archivedShows.map(show => (
177	                  <ShowCard key={show.id} show={show} />
178	                ))}
179	              </div>
180	            </CollapsibleContent>
181	          </Collapsible>
182	        )}
183	        
184	      </div>
185	    </Layout>
186	  );
187	}
